/* Detailed character rendering. Combat proxies remain separate from visual meshes. */
(function(root){
root.EdoCharacters={create(scene,shadows){
const B=BABYLON,V=B.Vector3,C=B.Color3;
const materials={},containers={},actors=new Set();let ready=false;
function material(name,hex,metallic=0,roughness=.65){const m=new B.PBRMaterial(name,scene);m.albedoColor=C.FromHexString(hex);m.metallic=metallic;m.roughness=roughness;m.environmentIntensity=.7;materials[name]=m;return m;}
const skin=material('weathered skin','#b18b71',0,.68),oniSkin=material('crimson hide','#8f2d25',0,.66),cloth=material('woven indigo','#26343a',0,.92),trousers=material('worn hemp','#575044',0,.95),hair=material('hair','#161613',0,.8),eyeWhite=material('eye white','#bdb6a2',0,.4),iris=material('iris','#261b13',0,.2),lip=material('lips','#765044',0,.65),iron=material('aged iron','#383c3a',.8,.33),steel=material('polished steel','#c8d1d1',.95,.23),leather=material('leather bindings','#382d23',0,.84),brass=material('aged brass','#a58a4c',.8,.4),ivory=material('horn and tusks','#bdb396',0,.48),tiger=material('tiger hide','#a38948',0,.9);
const ember=material('ember eyes','#d77c25',.1,.4);ember.emissiveColor=new C(.5,.13,.01);
// Deterministic microdetail; all textures are generated locally and shared across actors.
function noiseTexture(name,base,amount,bump=false){const size=128,data=new Uint8Array(size*size*4);let seed=71;for(let y=0;y<size;y++)for(let x=0;x<size;x++){seed=(seed*16807)%2147483647;const n=(seed/2147483647-.5)*amount;const weave=(Math.sin(x*Math.PI)+Math.cos(y*Math.PI))*.5;const idx=(y*size+x)*4;for(let c=0;c<3;c++)data[idx+c]=bump?(c===2?255:Math.max(0,Math.min(255,128+n*(c===0?1:-1)))):Math.max(0,Math.min(255,base[c]+n+weave*3));data[idx+3]=255;}const t=B.RawTexture.CreateRGBATexture(data,size,size,scene,true,false,B.Texture.TRILINEAR_SAMPLINGMODE);t.name=name;t.wrapU=t.wrapV=B.Texture.WRAP_ADDRESSMODE;t.uScale=t.vScale=bump?5:2;return t;}
skin.albedoTexture=noiseTexture('skin complexion',[175,137,112],12);skin.albedoColor=C.White();oniSkin.albedoTexture=noiseTexture('oni complexion',[142,47,35],22);oniSkin.albedoColor=C.White();skin.bumpTexture=noiseTexture('skin pores',[127,127,127],13,true);skin.bumpTexture.level=.09;oniSkin.bumpTexture=skin.bumpTexture;cloth.bumpTexture=noiseTexture('hemp weave',[127,127,127],35,true);cloth.bumpTexture.level=.13;trousers.bumpTexture=cloth.bumpTexture;iron.bumpTexture=noiseTexture('hammered iron',[127,127,127],18,true);iron.bumpTexture.level=.09;tiger.bumpTexture=cloth.bumpTexture;
function finish(mesh,m,parent){mesh.material=m;mesh.parent=parent;mesh.metadata={characterVisual:true};mesh.isPickable=false;mesh.receiveShadows=true;shadows.addShadowCaster(mesh);return mesh;}
function ell(n,x,y,z,sx,sy,sz,m,parent){const mesh=B.MeshBuilder.CreateSphere(n,{diameter:2,segments:16},scene);mesh.position.set(x,y,z);mesh.scaling.set(sx,sy,sz);return finish(mesh,m,parent);}
function tube(n,points,r,m,parent,radiusFunction){return finish(B.MeshBuilder.CreateTube(n,{path:points.map(p=>new V(...p)),radius:r,tessellation:10,radiusFunction,cap:B.Mesh.CAP_ALL},scene),m,parent);}
function lathe(n,profile,m,parent,x=0,z=0){const mesh=B.MeshBuilder.CreateLathe(n,{shape:profile.map(([r,y])=>new V(r,y,0)),tessellation:24,cap:B.Mesh.CAP_ALL},scene);mesh.position.set(x,0,z);return finish(mesh,m,parent);}
function joint(parent,x,y,z){const n=new B.TransformNode('anatomical joint',scene);n.parent=parent;n.position.set(x,y,z);return n;}
function face(parent,oni=false){const flesh=oni?oniSkin:skin;ell('sculpted head',0,1.94,0,.145,.2,.14,flesh,parent);ell('jaw',0,1.83,-.018,.115,.09,.11,flesh,parent);ell('nose bridge',0,1.94,-.136,.026,.06,.035,flesh,parent);ell('nose tip',0,1.904,-.166,.03,.024,.024,flesh,parent);for(const sign of [-1,1]){ell('cheekbone',sign*.092,1.9,-.1,.043,.043,.045,flesh,parent);ell('ear',sign*.15,1.94,.005,.024,.05,.033,flesh,parent);ell('inner ear',sign*.169,1.94,-.005,.006,.03,.017,lip,parent);ell('eyeball',sign*.059,1.977,-.12,.038,.016,.022,eyeWhite,parent);ell('pupil',sign*.059,1.977,-.141,.012,.013,.006,oni?ember:iris,parent);ell('nostril',sign*.019,1.893,-.175,.008,.006,.003,iris,parent);tube('brow',[[sign*.026,2.005,-.13],[sign*.058,2.012,-.135],[sign*.096,1.999,-.118]],.009,hair,parent);tube('upper eyelid',[[sign*.026,1.979,-.13],[sign*.059,1.99,-.141],[sign*.095,1.98,-.124]],.005,flesh,parent);}
tube('mouth',[[ -.052,1.846,-.119],[0,1.842,-.133],[.052,1.846,-.119]],.006,lip,parent);ell('lower lip',0,1.83,-.126,.043,.009,.01,lip,parent);ell('hair crown',0,2.066,.02,.148,.105,.135,hair,parent);ell('hair knot',0,2.165,.065,.045,.06,.05,hair,parent);
if(oni){for(const sign of [-1,1]){tube('curved oni horn',[[sign*.095,2.08,0],[sign*.16,2.24,-.01],[sign*.175,2.37,-.05],[sign*.14,2.42,-.08]],.045,ivory,parent,i=>.045*(1-i/3)+.002);tube('tusk',[[sign*.05,1.826,-.126],[sign*.062,1.89,-.164],[sign*.057,1.924,-.16]],.013,ivory,parent,i=>.014*(1-i/2)+.001);ell('heavy brow ridge',sign*.065,2.01,-.111,.055,.025,.03,flesh,parent);}ell('oni jaw',0,1.81,-.02,.136,.09,.122,flesh,parent);}}
function hands(parent,oni=false){const m=oni?oniSkin:skin;ell('hand',0,-.47,0,.048,.075,.035,m,parent);for(let i=0;i<4;i++)tube('finger',[[ -.033+i*.021,-.51,-.012],[-.033+i*.021,-.572,-.018],[-.033+i*.021,-.585,-.035]],.009,m,parent);tube('thumb',[[.043,-.46,0],[.065,-.5,-.01],[.047,-.528,-.025]],.013,m,parent);}
function katana(parent){tube('wrapped grip',[[0,-.53,0],[0,-.72,0]],.027,leather,parent);ell('tsuba',0,-.73,0,.07,.012,.05,brass,parent);tube('curved katana',[[0,-.75,0],[0,-1.03,.006],[0,-1.35,.025],[0,-1.58,.07]],.019,steel,parent,i=>.019*(1-i/4));for(let i=0;i<7;i++)tube('handle braid',[[-.025,-.54-i*.025,0],[.025,-.56-i*.025,0]],.004,ivory,parent);}
function sculpt(e){const model=new B.TransformNode('sculpted '+e.kind,scene);model.parent=e.root;const oni=e.kind==='oni';face(model,oni);const flesh=oni?oniSkin:skin;
lathe('neck',[[.07,1.6],[.075,1.7],[.075,1.8]],flesh,model);
if(oni){lathe('muscular torso',[[.18,.9],[.19,1.05],[.23,1.25],[.3,1.45],[.3,1.55],[.18,1.68]],flesh,model);for(const side of [-1,1]){ell('pectoral',side*.14,1.44,-.13,.155,.13,.115,flesh,model);ell('trapezius',side*.13,1.62,.04,.15,.09,.13,flesh,model);for(let i=0;i<3;i++)ell('abdominal',side*.07,1.24-i*.1,-.155,.076,.055,.043,flesh,model);}lathe('oni hide skirt',[[.23,.68],[.26,.78],[.245,.97],[.21,1.04]],tiger,model);for(let i=0;i<14;i++){const a=i/14*Math.PI*2;tube('tiger stripe',[[Math.sin(a)*.245,.72,Math.cos(a)*.245],[Math.sin(a+.08)*.25,.85,Math.cos(a+.08)*.25],[Math.sin(a)*.23,.98,Math.cos(a)*.23]],.01,hair,model);}}
else{lathe('kimono torso',[[.19,.94],[.22,1.08],[.23,1.28],[.27,1.5],[.23,1.62]],cloth,model);for(const sign of [-1,1])tube('crossed collar',[[sign*.075,1.68,-.1],[-sign*.08,1.4,-.2],[-sign*.17,1.18,-.16]],.026,trousers,model);for(let i=0;i<4;i++){const y=1.04+i*.015;const pts=[];for(let j=0;j<=24;j++){const a=j/24*Math.PI*2;pts.push([Math.sin(a)*.225,y,Math.cos(a)*.18]);}tube('rope belt',pts,.009,leather,model);}ell('obi knot',.16,1.08,-.18,.06,.05,.04,leather,model);}
const legs=[];for(const sign of [-1,1]){const leg=joint(model,sign*.125,.94,0);legs.push(leg);ell('thigh',0,-.2,.02,oni?.115:.105,.25,.115,oni?flesh:trousers,leg);ell('knee',0,-.45,-.015,.08,.08,.08,oni?flesh:trousers,leg);ell('calf',0,-.65,.025,.08,.2,.09,oni?flesh:trousers,leg);ell('ankle',0,-.84,0,.05,.08,.06,flesh,leg);ell('foot',0,-.9,-.065,.07,.04,.13,oni?flesh:leather,leg);if(!oni)for(let j=0;j<8;j++)tube('gaiter binding',[[-.075,-.5-j*.035,-.04],[.075,-.52-j*.035,-.04]],.006,leather,leg);}
const arms=[];for(const sign of [-1,1]){const arm=joint(model,sign*.3,1.57,0);arms.push(arm);ell('shoulder',0,0,0,.11,.115,.12,oni?flesh:cloth,arm);ell('upper arm',0,-.16,0,.085,.19,.09,oni?flesh:cloth,arm);ell('elbow',0,-.3,0,.065,.07,.065,flesh,arm);ell('forearm',0,-.36,0,.06,.11,.064,flesh,arm);hands(arm,oni);}
if(oni){const arm=arms[0];tube('kanabo shaft',[[0,-.53,0],[0,-1.25,0]],.04,leather,arm);lathe('forged club',[[.055,-1.6],[.14,-1.55],[.14,-.85],[.06,-.8]],iron,arm);for(let row=0;row<5;row++)for(let i=0;i<6;i++){const a=i/6*Math.PI*2;ell('club stud',Math.sin(a)*.145,-.93-row*.12,Math.cos(a)*.145,.028,.028,.028,steel,arm);}}
else{katana(arms[0]);const hat=B.MeshBuilder.CreateCylinder('woven kasa',{diameterTop:.08,diameterBottom:.67,height:.16,tessellation:40},scene);hat.position.y=2.16;finish(hat,trousers,model);for(let i=0;i<28;i++){const a=i/28*Math.PI*2;tube('straw rib',[[0,2.24,0],[Math.sin(a)*.33,2.08,Math.cos(a)*.33]],.003,leather,model);}}
e.detail={model,legs,arms};return model;}
function instantiated(container,parent,height,rotate=true){const result=container.instantiateModelsToScene(n=>'detail '+n,false,{doNotInstantiate:true});const wrap=new B.TransformNode('asset character',scene);for(const n of result.rootNodes)n.parent=wrap;wrap.computeWorldMatrix(true);let min=new V(Infinity,Infinity,Infinity),max=new V(-Infinity,-Infinity,-Infinity);for(const mesh of wrap.getChildMeshes()){mesh.computeWorldMatrix(true);const box=mesh.getBoundingInfo().boundingBox;min=V.Minimize(min,box.minimumWorld);max=V.Maximize(max,box.maximumWorld);mesh.metadata={characterVisual:true};mesh.isPickable=false;mesh.receiveShadows=true;shadows.addShadowCaster(mesh);}const scale=height/(max.y-min.y);wrap.scaling.setAll(scale);wrap.position.y=-min.y*scale;if(rotate)wrap.rotation.y=Math.PI;wrap.parent=parent;return{...result,wrap,scale};}
function install(e){if(e.root.isDisposed()||e.visualInstalled)return;const original=e.root.getChildMeshes();for(const m of original){m.visibility=0;shadows.removeShadowCaster(m);}e.visualInstalled=true;
const container=containers[e.kind==='oni'?'oni':'samurai'];if(!container)return;const avatar=instantiated(container,e.root,e.kind==='cavalry'?1.9:2.2);e.avatar=avatar;avatar.poseArm=avatar.wrap.getDescendants().find(n=>/RightArm$/.test(n.name));avatar.armRest=avatar.poseArm?.rotationQuaternion?.clone();avatar.idle=avatar.animationGroups.find(a=>/idle/i.test(a.name));avatar.walk=avatar.animationGroups.find(a=>/walk/i.test(a.name));avatar.run=avatar.animationGroups.find(a=>/run/i.test(a.name));avatar.baseY=avatar.wrap.position.y;
const hand=avatar.wrap.getDescendants().find(n=>/RightHand$/.test(n.name));if(hand){const weapon=joint(hand,0,0,0);hand.computeWorldMatrix(true);const handScale=new V();hand.getWorldMatrix().decompose(handScale);weapon.scaling.setAll(e.root.scaling.x/Math.max(.00001,Math.abs(handScale.x)));weapon.rotation.x=e.kind==='oni'?Math.PI/2:Math.PI;if(e.kind==='oni'){tube('kanabo shaft',[[0,.1,0],[0,-.9,0]],.035,leather,weapon);lathe('forged kanabo',[[.055,-1.25],[.13,-1.2],[.13,-.55],[.055,-.5]],iron,weapon);for(let row=0;row<4;row++)for(let i=0;i<6;i++){const a=i/6*Math.PI*2;ell('iron stud',Math.sin(a)*.14,-.64-row*.14,Math.cos(a)*.14,.025,.025,.025,steel,weapon);}}else{const bladeRoot=joint(weapon,0,.55,0);katana(bladeRoot);}}

if(e.kind==='samurai'||e.kind==='bandit'){for(const m of avatar.wrap.getChildMeshes())if(m.material){const copy=m.material.clone('samurai dark lacquer');copy.albedoColor=e.kind==='bandit'?new C(.64,.55,.46):new C(.5,.58,.64);copy.roughness=e.kind==='bandit'?.82:.55;m.material=copy;}}
if(e.kind==='shogun'){const banner=lathe('command pole',[[.013,0],[.013,2.5]],brass,e.root,.47,.15);const sheet=B.MeshBuilder.CreatePlane('command banner',{width:.42,height:.8,sideOrientation:B.Mesh.DOUBLESIDE},scene);sheet.position.set(.65,2,.15);finish(sheet,cloth,e.root);ell('gold crest',.65,2,.105,.09,.09,.01,brass,e.root);}
if(e.kind==='cavalry'&&containers.horse){avatar.wrap.position.y+=.55;avatar.mountedPose=avatar.wrap.getDescendants().filter(n=>/^(?:detail )?(LeftUpLeg|RightUpLeg|LeftLeg|RightLeg)$/.test(n.name)).map(n=>({node:n,rest:n.rotationQuaternion?.clone(),name:n.name}));const horse=instantiated(containers.horse,e.root,2.2,false);horse.wrap.rotation.y=Math.PI;e.horseAvatar=horse;ell('leather saddle',0,1.43,.02,.5,.1,.6,leather,e.root);}
const walk=avatar.idle??avatar.walk;if(walk){walk.start(true,1);if(!avatar.idle){walk.goToFrame(walk.from);walk.pause();}}avatar.playing='idle';}
function attach(e){actors.add(e);if(ready)install(e);}
function tick(e,practice){if(!e.visualInstalled)return;const walking=!practice&&!e.dead&&(e.action==='approach'||e.action==='charge');if(e.detail){const {legs,arms}=e.detail;legs.forEach((leg,i)=>leg.rotation.x=walking?Math.sin(e.phase+i*Math.PI)*.42:0);arms.forEach((arm,i)=>{arm.rotation.x=i===0?(e.action==='windup'?-2.5:e.action==='combo'?-.6:-.6):(walking?Math.sin(e.phase)*.15:0);});if(e.rage){e.detail.model.scaling.x=1.05;}return;}const a=e.avatar;if(!a)return;const next=walking&&e.kind!=='cavalry'?(e.action==='charge'?'run':'walk'):'idle';if(a.playing!==next){a.animationGroups.forEach(g=>g.stop());const clip=next==='run'?a.run:next==='idle'?(a.idle??a.walk):a.walk;if(clip){clip.start(true,next==='run'?1.2:1);if(next==='idle'&&!a.idle){clip.goToFrame(clip.from);clip.pause();}}a.playing=next;}a.wrap.rotation.x=e.action==='windup'?-.12:e.action==='combo'?.12:0;if(e.kind==='cavalry'){a.wrap.position.y=a.baseY+.55+(walking?Math.sin(e.phase)*.025:0);if(e.horseAvatar)e.horseAvatar.wrap.rotation.x=walking?Math.sin(e.phase)*.018:0;}}
function dispose(e){actors.delete(e);e.avatar?.animationGroups.forEach(g=>g.dispose());e.avatar?.skeletons.forEach(s=>s.dispose());if(e.avatar)for(const m of e.avatar.wrap.getChildMeshes())if(m.material?.name==='samurai dark lacquer')m.material.dispose();}
scene.onAfterAnimationsObservable.add(()=>{for(const e of actors){const a=e.avatar;if(!a||e.dead)continue;if(a.mountedPose)for(const pose of a.mountedPose){if(!pose.rest)continue;const upper=/UpLeg/.test(pose.name);const q=B.Quaternion.RotationAxis(B.Axis.X,upper?-1.0:1.35);pose.node.rotationQuaternion=pose.rest.multiply(q);}if(!a.poseArm||!a.armRest)continue;if(e.action==='windup'||e.action==='combo'||e.action==='recover'){const angle=e.action==='windup'?-1.7:e.action==='combo'?.6:.2;a.poseArm.rotationQuaternion=a.armRest.multiply(B.Quaternion.RotationAxis(B.Axis.X,angle));}}});
const loading=Promise.all(['samurai','horse','oni'].map(async key=>{containers[key]=await B.SceneLoader.LoadAssetContainerAsync('assets/characters/',key+'.glb',scene);})).then(()=>{ready=true;for(const e of actors)if(!e.root.isDisposed())install(e);}).catch(error=>{console.error('Detailed character assets could not load',error);for(const e of actors){if(e.root.isDisposed()||e.visualInstalled)continue;sculpt(e);for(const m of e.root.getChildMeshes())if(!m.metadata?.characterVisual)m.visibility=0;e.visualInstalled=true;}throw error;});
return{attach,tick,dispose,loading};
}};
})(window);
